    urlutils.addCatalogToInternalUris = function (catalog) {
      catalog.forEach(function(node) {
          if (node.hasOwnProperty('href')){
            var href = window.location.hostname+node.href;
            if (node.href.indexOf('index.html' < 0)){
                href += "index.html"
                node.href = node.href+"index.html";
            }
            internalUris[href] = true;
          }
          if (node.hasOwnProperty('topics')){
            urlutils.addCatalogToInternalUris(node.topics);
          }
      });
    };

    urlutils.isUrlInternal = function (href) {
        var target = $.parseURL(href).target;
        return internalUris.hasOwnProperty(target);
    };

