        if (!schema.type && !hideAny) {
            schema.__type = "any";
        }
        if (schema.format) {
            schema.__type = schema.format;
        }
        if ((schema.__type === "any" || schema.__type === "object") && schema.title) {
            schema.__type = schema.title;
        }
        var result = options.fn(schema);
        delete schema.__type;
        return result;
