define('text!../../ohc-common/templates/utility-bar/scope/scopechip.hbs',[],function () { return '<div>\n  <div id="search-bar-scope" aria-label="Search Scope" role="group">\n    <div id="search-bar-scope-book" class="{{#if scopeIcon}}{{scopeIcon}}{{/if}}" role="none" aria-hidden="true"></div>\n    <div id="white-pipe" style="display: none; height: 16px; width: 1px; background-color: #fcfbfa; opacity: 0.15; padding-right: 1px;"></div>\n    <span id="search-bar-scope-text">{{#if searchBarScopeText}}{{searchBarScopeText}}{{/if}}</span>\n    <button id="search-bar-scope-close" aria-label="Remove"><span id="search-bar-scope-close-icon"></span></button>\n\n    <div id="search-scope-tooltip" class="tooltip tooltip-hide" style="opacity: 1;" role="tooltip">\n      <div class="tooltip-inner">\n        <div id="search-bar-scope-tooltip" aria-hidden="true">\n          <p class="grayed-font">Search is scoped to:</p>\n          <p class="black-font">{{#if searchBarScopeText}}{{searchBarScopeText}}{{/if}}</p>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>';});

define('book-scope-helper',['jquery'], function ($) {
  var PAGES_ENDPOINT = '/apps/ohcsearchclient/api/v1/search/pages';
  var ASSETS_ENDPOINT = '/apps/ohcsearchclient/api/v1/search/assets';

  function pagesService(params) {
    return isHttps() ? $.getJSON(PAGES_ENDPOINT, params) : $.Deferred().reject();
  }

  function assetsService(params) {
    return isHttps() ? $.getJSON(ASSETS_ENDPOINT, params) : $.Deferred().reject();
  }

  function isHttps() {
    return window.location.protocol === 'https:';
  }

  function BookScopeHelper() {}

  BookScopeHelper.resolveFirstAssetTitle = function (promise, response) {
    var firstHit = response.hits.slice(0, 1)[0] || {};
    promise.resolve(this.mapFirtsAssetTitle(firstHit));
  };

  BookScopeHelper.mapFirtsAssetTitle = function (firstHit) {
    var source = firstHit._source || {};
    return source.asset_title || null;
  };

  BookScopeHelper.resolveFirstTitle = function (promise, response) {
    var firstHit = response.hits.slice(0, 1)[0] || {};
    promise.resolve(this.mapFirstAssetHit(firstHit));
  };

  BookScopeHelper.mapFirstAssetHit = function (firstHit) {
    var source = firstHit._source || {};
    return source.title || null;
  };

  BookScopeHelper.rejectWithNull = function (promise) {
    promise.reject(null);
  };

  BookScopeHelper.getTitleFromAssets = function getTitleFromAssets(args) {
    var titlePromise = $.Deferred();
    var book = args.book || undefined;
    var library = args.library || undefined;

    assetsService({ book: book, library: library })
      .done(this.resolveFirstTitle.bind(this, titlePromise))
      .fail(this.rejectWithNull.bind(this, titlePromise));

    return titlePromise.promise();
  };

  BookScopeHelper.getAssetTitleFromPages = function (args) {
    var assetTitlePromise = $.Deferred();

    pagesService(args)
      .done(this.resolveFirstAssetTitle.bind(this, assetTitlePromise))
      .fail(this.rejectWithNull.bind(this, assetTitlePromise));

    return assetTitlePromise.promise();
  };

  return function computeBookLabel(args) {
    var labelPromise = $.Deferred();

    var pagesOrAssetsPromise = $.when()
      .then(function () { return $.when(BookScopeHelper.getAssetTitleFromPages(args)); })
        .then(function (assetTitle) { return assetTitle || BookScopeHelper.getTitleFromAssets(args); });

    $.when(pagesOrAssetsPromise).then(function (titleFromEndpoints) {
      labelPromise.resolve(titleFromEndpoints || args.book || args.library || 'unknown');
    });

    return labelPromise.promise();
  }
});


define('product-scope-helper',['jquery'], function ($) {
  var PRODUCTS_ENDPOINT = '/apps/ohcsearchclient/api/v1/search/products';

  function productsService(params) {
    return window.location.protocol === 'https:' ? $.getJSON(PRODUCTS_ENDPOINT, params) : $.Deferred().reject();
  }

  function mapFirstProductName(hit) {
    var generalProdName = hit._source && hit._source.name;
    if (hit._source.breadcrumbs) {
      var prodName = hit._source.breadcrumbs.product && hit._source.breadcrumbs.product.name;
      var prodCategory = hit._source.breadcrumbs.category && hit._source.breadcrumbs.category.name;
      var prodRelease = hit._source.breadcrumbs.release && hit._source.breadcrumbs.release.name;
      var prodSuite = hit._source.breadcrumbs.suite && hit._source.breadcrumbs.suite.name;

      if (prodName && prodRelease) return prodName + ' ' + prodRelease;
      if (prodSuite && prodRelease) return prodSuite + ' ' + prodRelease;
      if (prodCategory && prodRelease) return prodCategory + ' ' + prodRelease;
    }
    return generalProdName;
  }

  function resolveFirstProductName(promise, response) {
    if(response.hits.length > 0) {
	    var firstHit = response.hits.slice(0, 1)[0] || {};
	    promise.resolve(mapFirstProductName(firstHit));
    } else {
      promise.reject(null);
    }
  }

  function rejectWithNull(promise) {
    promise.reject(null);
  }

  return function computeProductLabel(args) {
    var labelPromise = $.Deferred();
    var servicePromise = $.Deferred();

    productsService({ id: args.product })
      .done(resolveFirstProductName.bind(null, servicePromise))
      .fail(rejectWithNull.bind(null, servicePromise));

    servicePromise.always(function (productsEndpointValue) {
      labelPromise.resolve(productsEndpointValue || args.product || args.category || 'unknown');
    });
    return labelPromise.promise();
  };
});

define('solution-scope-helper',['jquery'], function ($) {
  return function computeSolutionLabel() {
    return $.Deferred().resolve('Architecture Center').promise();
  };
});

define('learn-scope-helper',['jquery'], function ($) {
  return function computeLearnLabel() {
    return $.Deferred().resolve('Learn').promise();
  };
});

define('scope-helper-factory',['book-scope-helper', 'product-scope-helper', 'solution-scope-helper', 'learn-scope-helper', 'jquery'],
  function (computeBookLabel, computeProductLabel, computeSolutionLabel, computeLearnLabel, $) {
  function ScopeHelperFactory() {}

  function getTitleFromMeta(args) {
    var title = $('meta[name="dcterms.title"]').attr('content');
    return $.Deferred().resolve(title || args.book || args.product || args.library || 'unknown').promise();
  }

  ScopeHelperFactory.getMetaLabelComputer = function (scopeParams) {

    if (this.isFAQ(scopeParams)) {
      return {
        compute: computeProductLabel,
        args: { product: scopeParams.library },
        iconClass: 'scope-product-icon'
      };
    }
    if (this.isPageArticle()) {
      return {
        compute: computeProductLabel,
        args: { product: scopeParams.product || scopeParams.category },
        iconClass: 'scope-product-icon'
      };
      
    }
    if (this.isSolutionsScope(scopeParams)) {
      return {
        compute: computeSolutionLabel,
        args: null,
        iconClass: 'scope-solutions-icon'
      };
    }
    if (this.isLearnScope(scopeParams)) {
      return {
        compute: computeLearnLabel,
        args: null,
        iconClass: 'scope-learn-icon'
      };
    }
    if (this.isCategorySolutions(scopeParams)) {
      return {
        compute: getTitleFromMeta,
        args: $.extend({}, scopeParams),
        iconClass: 'scope-product-icon'
       };
    }
    if (this.isBookScope(scopeParams)) {
      return {
        compute: getTitleFromMeta,
        args: $.extend({}, scopeParams),
        iconClass: 'scope-book-icon'
      };
    }
    if (this.isProductScope(scopeParams)) {
      return {
        compute: computeProductLabel,
        args: { product: scopeParams.product || scopeParams.category },
        iconClass: 'scope-product-icon'
      };
    }
    
    return { compute: $.Deferred().resolve('unknown').promise(), args: null, iconClass: '' };
  }

  ScopeHelperFactory.isBookScope = function (scopeParams) {
    return typeof scopeParams.book !== 'undefined' || typeof scopeParams.library !== 'undefined';
  };

  ScopeHelperFactory.isProductScope = function (scopeParams) {
    return typeof scopeParams.product !== 'undefined' || typeof scopeParams.category !== 'undefined';
  };

  ScopeHelperFactory.isSolutionsScope = function (scopeParams) {
    return typeof scopeParams.product !== 'undefined' && scopeParams.product === 'en/solutions';
  };

  ScopeHelperFactory.isCategorySolutions = function (scopeParams) {
    return typeof scopeParams.category !== 'undefined' && scopeParams.category === 'solutions';
  };

  ScopeHelperFactory.isLearnScope = function (scopeParams) {
    return typeof scopeParams.category !== 'undefined' && scopeParams.category === 'en/learn';
  };

  ScopeHelperFactory.isPageArticle = function () {
    var rootElement = $('html');
    return rootElement.hasClass('article') && rootElement.hasClass('letter-style');
  };

  ScopeHelperFactory.isFAQ = function (scopeParams) {
    return $('.ohc-standalone').length > 0 && typeof scopeParams.library !== 'undefined';
  };

  return ScopeHelperFactory;
});

define('utility-bar',['jquery', 'handlebars', 'scope-helper-factory'], function ($, Handlebars, ScopeHelperFactory) {
  var doneTypingInterval = 800;
  var utilityBar = {};
  var availableScopeParams = ['library', 'book', 'product', 'category'];
  var typingTimer;
  var previewResultsAlert = '';
  var tooltipTimeout = null;
  var callbackEnterListener = null;
  var clearEnterListenerOnScopeRemoval = false;
  var activeScope = null;
  var pagesSearchPromise = null;
  var productsSearchPromise = null;
  var enterPressed = false;

  /**
   * Initialize the different event handlers needed for the utility bar to work properly, this function should be called
   * before any other function.
   * @param source
   */
  utilityBar.init = function (source) {
    var template = Handlebars.compile(source);
    $(window).on("load", function () {
      $("html[dir=rtl]").find(".u02nav").addClass("rtl");
    });
    assignStylePreview();

    var searchBarInput = $('#search-bar-input');
    searchBarInput.on('input', function () {
      var inputValue = $(this).val();
      clearTimeout(typingTimer);
      if (inputValue && inputValue.trim().length > 0) {
        enterPressed = false;
        typingTimer = setTimeout(getResults, doneTypingInterval);
      }
    });

    searchBarInput.keyup(function (e) {
      var keyArrows = ['ArrowDown', 'Down'];
      if (keyArrows.indexOf(e.key) !== -1) {
        addAccessibilityPreview();
      }
    })

    $(document).click(function (e) {
      if (e.target.closest('#results-preview') === null) {
        $('#preview-container').addClass('preview-hide');
      }
    })

    $(document).keydown(function (e) {
      var keyArrows = ['ArrowDown', 'Down'];
      if (keyArrows.indexOf(e.key) === -1 && e.target.closest('#results-preview') === null) {
        $('#preview-container').addClass('preview-hide');
      }
    })

    $(window).resize(function () {
      assignStylePreview();
    });

    $('#search-bar-container .u02searchform').on('submit', function (event) {
      if (callbackEnterListener !== null) {
        event.preventDefault();
        enterPressed = true;
        clearTimeout(typingTimer);
        abortSearchPromises();
        callbackEnterListener(searchBarInput.val(), activeScope)
      }
    })

    $('#skip-search').click(function (e) {
      e.preventDefault();
      searchBarInput.focus()
    })

    $('#search-bar-container').on('click', '#search-bar-scope-close', function(e) {
      $('#search-bar-container form')
        .find('input[name=product], input[name=category], input[name=book], input[name=library]')
          .remove();
      window.clearTimeout(tooltipTimeout);
      var searchBarScope = $('#search-bar-scope:not([style*="display: none"])');
      $('#search-scope-tooltip').addClass('tooltip-hide');
      searchBarScope.hide();
      activeScope = null
      if (clearEnterListenerOnScopeRemoval) {
        callbackEnterListener = null
        clearEnterListenerOnScopeRemoval = false
      }
    });

    function getConcatArray(arrayRes, arrayProducts) {
      for (var i = 0; i < arrayProducts.length && arrayRes.length + arrayProducts.length > 8; i++) {
       arrayRes.pop();
      }
      return [].concat(arrayProducts, arrayRes);
    }

    function validateResults(dataProducts, data) {
      if (data.hits.length > 0 || dataProducts.hits.length > 0) {
        var arrayProducts = parseResultsProducts(dataProducts);
        var indexCards = arrayProducts.length !== 0 ? arrayProducts.length : -1;
        var arrayRes = parseResults(data);
        var arrayResults = getConcatArray(arrayRes, arrayProducts);
        var wrapper = {
          results: arrayResults,
          hrefAll: '/search/?' + categoryAndProducts(),
          searchterm: searchBarInput.val(),
          productsIndex: indexCards,
          productsIndexMin: indexCards - 1
        };
        document.getElementById('results-preview').innerHTML = template(wrapper)
        $('#no-results-preview, #error-results-preview').addClass('preview-hide');
        $('#results-preview, #preview-container').removeClass('preview-hide');
      } else {
        $('#results-preview, #error-results-preview').addClass('preview-hide');
        $('#no-results-preview, #preview-container').removeClass('preview-hide');
      }
      assignStylePreview();
      validatePreviewResultsAlert();
    }

    function getResults() {
      if (window.location.protocol === 'https:') {
        var theUrl = window.location.protocol + '//' + window.location.hostname;
        pagesSearchPromise = $.ajax({
          url: theUrl + '/apps/ohcsearchclient/api/v1/search/products',
          type: 'get',
          dataType: 'json',
          data: getAllParamsProducts()
        });
        productsSearchPromise = $.ajax({
          url: theUrl + '/apps/ohcsearchclient/api/v1/search/pages',
          type: 'get',
          dataType: 'json',
          data: getAllParams()
        });
        $.when(
            pagesSearchPromise, productsSearchPromise
        ).then(
          function(dataProducts, data){
            clearSearchPromises();
            if (dataProducts.length !== 0 && data.length !== 0) {
              validateResults(dataProducts[0],data[0]);
            } else {
              showPreviewError();
            }
          },
          function () {
            clearSearchPromises();
            if (!enterPressed) showPreviewError();
          });
      }
    }

    function clearSearchPromises () {
      pagesSearchPromise = null;
      productsSearchPromise = null;
    }

    function abortSearchPromises () {
      if (pagesSearchPromise != null) pagesSearchPromise.abort();
      if (productsSearchPromise != null) productsSearchPromise.abort();
      clearSearchPromises();
    }
  }

  /**
   * Adds a callback function for the enter event, expected function signature is (input, activeScope) where input is a
   * string and activeScope is a object with title and any of the following depending on the meta tags: library, book,
   * product, category. This listener will remain even if the scopechip is removed.
   * @param {function} listener
   */
  utilityBar.addPersistentEnterListener = function(listener) {
    callbackEnterListener = listener;
  }

  /**
   * Adds a callback function for the enter event, expected function signature is (input, activeScope) where input is a
   * string and activeScope is a object with title and any of the following depending on the meta tags: library, book,
   * product, category. This listener will be removed once the scopechip is removed.
   * @param {function} listener
   */
  utilityBar.addEnterListener = function (listener) {
    callbackEnterListener = listener;
    clearEnterListenerOnScopeRemoval = true;
  }

  /**
   * Renders the scopechip based on the hidden inputs added to the form
   * @param template
   */
  utilityBar.handleScopeParams = function (template) {
    var scopeSelector = '#search-bar-scope';

    var scopeQueryParams = getScopeFilters();
    if (scopeQueryParams.length > 0) {
      var renderScopeChip = function (scopeChipTemplate, data) {
        var scopeTemplate = Handlebars.compile(scopeChipTemplate);
        var html = scopeTemplate(data);

        $(scopeSelector).replaceWith($(scopeSelector, html));
        $('#search-bar-scope-close').attr(
          'aria-description', 'Search scoped to this page. Press enter to remove scope'
        );
        $(scopeSelector).show();
        scopeTooltipHandleMediaQueries();
      };
      showScopeFilter(scopeQueryParams, renderScopeChip.bind(null, template));
    }
    else $(scopeSelector).hide();
  }

  /**
   * Adds a book and library hidden input to the form based on the dcterms.isVersionOf and dcterms.product meta tags respectively,
   * they both should exists in order to add the hidden inputs, any other hidden input is removed.
   */
  utilityBar.rewriteBookParams = function() {
    var book = $('meta[name="dcterms.isVersionOf"]').attr('content');
    var dctermProduct = $('meta[name="dcterms.product"]').attr('content');
    var searchForm = $('#search-bar-container .u02searchform');
    
    if (book && dctermProduct) {
      var library = dctermProduct.split(/,|;/)[0];
      $('#search-bar-container form input').each(function () {
        if (availableScopeParams.indexOf($(this).attr('name')) > -1) $(this).remove();
      });
      searchForm.append('<input type="hidden" name="book" value="' + book.toUpperCase() + '">');
      searchForm.append('<input type="hidden" name="library" value="' + library + '">');
    } else if (dctermProduct) {
      setSearchHiddenInputForDcTerms('product');
    }
  }

  /**
   * Adds a product hidden input to the form based on the dcterms.product meta tag
   */
  utilityBar.rewriteProductParams = function() {
    setSearchHiddenInputForDcTerms('product')
  }

  /**
   * Adds a product hidden input to the form based on the dcterms.category meta tag
   */
  utilityBar.rewriteCategoryParams = function() {
    setSearchHiddenInputForDcTerms('category')
  }

  /**
   * Convenience method to add a scopechip from the dcterms meta tags, the more specific scope will be set.
   * @param template
   */
  utilityBar.addScopeChipFromMetaTags = function(template) {
    this.rewriteCategoryParams()
    this.rewriteProductParams()
    this.rewriteBookParams()
    this.handleScopeParams(template);
  }

  utilityBar.hideSearchBar = function() {
    document.querySelectorAll('.u02menu')[0].style.visibility = 'hidden'
    document.getElementById('search-bar-container').style.display = 'none'
    document.getElementById('preview-container').style.display = 'none'
    document.getElementById('u02search').style.display = 'none'
    document.querySelectorAll('.u02tools')[0].style.visibility = 'hidden'
    document.querySelectorAll('.u02w1')[0].style.display = 'flex'
    document.querySelectorAll('.u02local')[0].style.display = 'contents'
    document.querySelectorAll('.u02localw1')[0].style.marginLeft = '40px'
    const ua = window.navigator.userAgent;
    const msie = ua.indexOf("MSIE ");
    if (msie > 0 || !!navigator.userAgent.match(/Trident.*rv\:11\./)) {
      document.querySelectorAll('.u02local')[0].css("width", "")
    } else {
      document.querySelectorAll('.u02local')[0].style.position = 'fixed'
      document.querySelectorAll('.u02local')[0].style.marginLeft = '68px'
    }
  }

  function setSearchHiddenInputForDcTerms(term) {
    var value = $('meta[name="dcterms.' + term + '"]').attr('content');
    if (value) {
      var existingValue = $('#search-bar-container .u02searchform input[name=' + term + ']');
      if (existingValue.length) {
        existingValue.attr('value', value.replace(/\;/g,','));
      } else {
        $("#search-bar-container .u02searchform").append('<input aria-hidden="true" type="hidden" name="' + term + '" value="' + value.replace(/\;/g,",") + '">');
      }
    }
  }

  function initScopeTooltip() {
    $('#search-bar-scope #search-bar-scope-text').show();
    $('#search-bar-scope #white-pipe').hide();
    var searchBarScope = $('#search-bar-scope');
    var searchScopeToolTip = $('#search-scope-tooltip')
    searchBarScope.off('click');
    searchBarScope.on('focusin mouseover', function() {
      window.clearTimeout(tooltipTimeout);
      tooltipTimeout = setTimeout(function () {
        searchScopeToolTip.removeClass('tooltip-hide');
      }, 1000);
    });
    searchBarScope.on('focusout mouseout', function() {
      window.clearTimeout(tooltipTimeout);
      tooltipTimeout = setTimeout(function () {
        searchScopeToolTip.addClass('tooltip-hide');
    	}, 100);
    });
  }

  function setupSTooltipMidScreens() {
    initScopeTooltip();
    $('#search-bar-scope #search-bar-scope-text').hide();
    $('#search-bar-scope #white-pipe').show();
  }

  function setupSTooltipSmallScreens() {
    setupSTooltipMidScreens();
    var searchBarScope = $('#search-bar-scope');
    searchBarScope.off('focusin mouseover');
    searchBarScope.off('focusout mouseout');
    searchBarScope.on('click', function () {
      $('#search-scope-tooltip').toggleClass('tooltip-hide');
    });
  }

  function scopeTooltipHandleMediaQueries() {
    var bigScreensMQ = window.matchMedia('(min-width: 1024px)');
    var midScreensMQ = window.matchMedia('(max-width: 1023px) and (min-width: 768px)');
    var smallScreensMQ = window.matchMedia('(max-width: 767px)');

    if (bigScreensMQ.matches) initScopeTooltip();
    else if (midScreensMQ.matches) setupSTooltipMidScreens();
    else if (smallScreensMQ.matches) setupSTooltipSmallScreens();

    $(window).resize(function () {
      if (bigScreensMQ.matches) initScopeTooltip();
      else if (midScreensMQ.matches) setupSTooltipMidScreens();
      else if (smallScreensMQ.matches) setupSTooltipSmallScreens();
    });
  }

  function categoryAndProducts() {
    var catProdParamenter = '';
    $('#search-bar-container > form.u02searchform input').each(function (i, element) {
      if(i > 0){
        catProdParamenter += '&';
      }
      catProdParamenter += encodeURIComponent($(element).attr('name')) + '=' + encodeURIComponent($(element).val());
    });
    return catProdParamenter;
  }

  function requestAllParams(arrayBan) {
    var data = {};
    $('#search-bar-container > form.u02searchform input').each(function (i, element) {
      if (arrayBan.length === 0 || arrayBan.indexOf($(element).attr('name')) === -1) {
        data[$(element).attr('name')] = $(element).val();
      }
    });
    return data;
  }

  function getAllParams() {
    var data = requestAllParams([]);
    data.start = '0';
    data.pg = '1';
    data.size = '8';
    data.lang = getCurrentLanguage();
    return data;
  }

  function getAllParamsProducts() {
    var data = requestAllParams(['category', 'product']);
    data.start = '0';
    data.pg = '1';
    data.size = '2';
    data.type = 'product';
    data.lang = 'en';
    return data;
  }

  function showPreviewError() {
    $('#no-results-preview, #results-preview').addClass('preview-hide');
    $('#error-results-preview, #preview-container').removeClass('preview-hide');
    assignStylePreview();
    validatePreviewResultsAlert();
  }

  function assignStylePreview() {
    var previewContainer = $('#preview-container');
    var searchBarContainer = $('#search-bar-container');
    const previewSeparation = searchBarContainer.height() + 3;
    previewContainer.css('width', searchBarContainer.width())
    previewContainer.offset({ left: searchBarContainer.offset().left })
    previewContainer.offset({ top: searchBarContainer.offset().top + previewSeparation});
  }

  function parseResults(data) {
    var plainResults = data.hits;
    var parsedResults = [];
    plainResults.forEach(function (element) {
      var resultObject = {};
      var domain = element._source.domain;
      var contentType = element._source.content_type;

      resultObject.title = element._source.title;
      resultObject.url = element._source.url;
      resultObject.breadcrumb = parseBreadcrumb(element);
      if (element._source.url.substring(element._source.url.lastIndexOf('.') + 1) === 'pdf') {
        resultObject.pdf = true;
      }
      if (domain === 'www.youtube.com' || contentType.indexOf('WM147094') !== -1) {
        resultObject.video = true;
      }
      parsedResults.push(resultObject)
    })
    return parsedResults;
  }

  function parseResultsProducts(data) {
    var plainProducts = data.hits;
    var parsedProducts = [];
    if (plainProducts.length !== 0) {
      plainProducts.forEach(function (element) {
        var resultObjectProduct = {};
        resultObjectProduct.title = element._source.name;
        resultObjectProduct.url = element._source.href.indexOf('http') !== -1 ? element._source.href : 'https://' + window.location.hostname+element._source.href;
        parsedProducts.push(resultObjectProduct);
      });
    }
    return parsedProducts;
  }

  function parseBreadcrumb(elem) {
    var breadcrumbs = elem._source.breadcrumbs;
    var tempBreadcrumb = '';

    if (breadcrumbs !== undefined && Object.keys(breadcrumbs).length > 0) {
      if(breadcrumbs.hasOwnProperty('product') && breadcrumbs.hasOwnProperty('release')) {
        tempBreadcrumb = breadcrumbs['product'].name + ' ' + breadcrumbs['release'].name;
      } else if(breadcrumbs.hasOwnProperty('product')){
        tempBreadcrumb = breadcrumbs['product'].name;
      } else if (breadcrumbs.hasOwnProperty('category')){
        tempBreadcrumb = breadcrumbs['category'].name;
      }
    } else {
      var hostName = elem._source.domain;

      if (hostName.match(/(docs.oracle.com|docs-stage.oracle.com|docs-uat.us.oracle.com)/g)) {
        tempBreadcrumb = 'Help Center';
      } else if (hostName.match(/(www.oracle.com)/g)) {
        tempBreadcrumb = 'Oracle.com';
      } else if (hostName.match(/(support.oracle.com)/g)) {
        tempBreadcrumb = 'Support';
      } else if (hostName.match(/(docs.cloud.oracle.com)/g)) {
        tempBreadcrumb = 'Oracle Cloud Infrastructure';
      } else if (hostName.match(/(oracle)/g)) {
        tempBreadcrumb = hostName.charAt(0).toUpperCase() + hostName.slice(1);
      } else {
        tempBreadcrumb = hostName;
      }
    }
    return tempBreadcrumb;
  }

  function addAccessibilityPreview() {
    var previewResultsContainers = document.querySelectorAll('.preview-result-container');
    var keyArrowDown = ['ArrowDown', 'Down'];
    var keyArrowUp = ['ArrowUp', 'Up'];

    if (previewResultsContainers[0]) {
      previewResultsContainers[0].focus();
    }
    for (var i = 0; i < previewResultsContainers.length; i++) {
      $(previewResultsContainers[i]).data('i', i)
      previewResultsContainers[i].addEventListener('keyup', function (e) {
        e.preventDefault();
        validatePreviewResultsFocus(previewResultsContainers, $(this).data('i'), e);
      });
      previewResultsContainers[i].addEventListener('keydown', function (e) {
        if (e.key === 'Tab') {
          e.preventDefault();
          var previewContainer = document.getElementById('preview-container');
          previewContainer.classList.add('preview-hide');
          document.querySelector('#search-bar-input').focus();
        }
      });
    }

    window.addEventListener('keydown', function (e) {
      var previewContainer = document.getElementById('preview-container');
      if ((keyArrowDown.indexOf(e.key) !== -1 || keyArrowUp.indexOf(e.key)) !== -1
        && getComputedStyle(previewContainer).display !== 'none') {
        e.preventDefault();
      }
    });
  }

  function validatePreviewResultsFocus(previewResultsContainers, i, e) {
    var keyArrowDown = ['ArrowDown', 'Down'];
    var keyArrowUp = ['ArrowUp', 'Up'];
    var next = previewResultsContainers[i + 1];
    var previous = previewResultsContainers[i - 1];

    if (keyArrowDown.indexOf(e.key) !== -1) {
      if (i === previewResultsContainers.length - 1) {
        next = previewResultsContainers[0];
      }
      next.focus();
    } else if (keyArrowUp.indexOf(e.key) !== -1) {
      if (i === 0) {
        previous = previewResultsContainers[previewResultsContainers.length - 1];
      }
      previous.focus();
    } else if (e.key === 'Enter') {
      var link = previewResultsContainers[i].closest('a');
      link.click();
    }
  }

  function validatePreviewResultsAlert() {
    var alertLabel = document.querySelector('#preview-results-alert');
    if (previewResultsAlert === 'New list of preview search results are loaded (links open on the same page), use arrow keys to move through the elements') {
      previewResultsAlert = '';
    } else {
      previewResultsAlert = 'New list of preview search results are loaded (links open on the same page), use arrow keys to move through the elements';
    }
    alertLabel.innerText = previewResultsAlert;
  }

  function getScopeFilters() {
    return $('#search-bar-container form')
      .serializeArray()
      .filter(function (searchFields) { return availableScopeParams.indexOf(searchFields.name) > -1 });
  }

  function showScopeFilter(scopeParams, renderCallback) {
    activeScope = {};
    scopeParams.forEach(function (param) { activeScope[param.name] = param.value; });

    var labelComputerObj = ScopeHelperFactory.getMetaLabelComputer(activeScope);
    var compute = labelComputerObj.compute;
    var args = labelComputerObj.args;
    var iconClass = labelComputerObj.iconClass;

    compute(args).done(function (label) {
      activeScope.title = label;
      renderCallback({ scopeIcon: iconClass, searchBarScopeText: label });
    });
  }

  // polyfill closest
  if (!Element.prototype.matches) {
    Element.prototype.matches = Element.prototype.msMatchesSelector ||
      Element.prototype.webkitMatchesSelector;
  }
  if (!Element.prototype.closest) {
    Element.prototype.closest = function (s) {
      var el = this;

      do {
        if (Element.prototype.matches.call(el, s)) return el;
        el = el.parentElement || el.parentNode;
      } while (el !== null && el.nodeType === 1);
      return null;
    };
  }

  function getCurrentLanguage() {
    const supportedLanguages = ['ar', 'de', 'nl', 'ru', 'ro', 'th', 'pt-br', 'hu', 'sk', 'pl', 'he', 'da', 'fr', 'fr-ca', 'sv', 'fi', 'el', 'cs', 'fr', 'hr', 'tr', 'zh-tw', 'zh-cn', 'es', 'en', 'no', 'pt', 'it', 'ja', 'ko'];
    const documentLang = document.documentElement.lang;
    const documentLocationSearchLang = document.location.search.match(/(?<=lang=)(.*?)(?=\&)/g);
    const documentLocationSearchLangEnd = document.location.search.match(/(?<=lang=)(.*?)$/g);
    let currentLang = 'en';

    if(supportedLanguages.includes(documentLang)) {
      currentLang = documentLang;
    } else if (documentLocationSearchLang && supportedLanguages.includes(documentLocationSearchLang[0])) {
      currentLang = documentLocationSearchLang[0];
    } else if (documentLocationSearchLangEnd && supportedLanguages.includes(documentLocationSearchLangEnd[0])) {
      currentLang = documentLocationSearchLangEnd[0];
    }

    return currentLang;
  }

  Handlebars.registerHelper('templateLang', function() {
    return getCurrentLanguage();
  });

  Handlebars.registerHelper('iff', function(a, operator, b, opts) {
    var bool = false;
    switch(operator) {
       case '==':
           bool = a === b;
           break;
       case 'gt':
           bool = a > b;
           break;
       case 'lt':
           bool = a < b;
           break;
       case '!=':
           bool = a !== b;
           break;
       default:
           throw "Unknown operator " + operator;
    }
    if (bool) {
        return opts.fn(this);
    } else {
      return opts.inverse(this);
    }
  });

  return utilityBar;
});

define('inline-helper-factory',['jquery'], function ($) {

    const PRODUCT_GROUP = "product-groups";
    const LATEST_DOCS = "latest-docs";
    const PREVIOUS_RELEASES = "previous-releases";
    const PROMO_RELEASES = "promo-releases";
    const SEARCH_ENABLED = "search-enabled";
    const contentNameRoleGeneral = '*';

    function InlineHelperFactory() {}

    InlineHelperFactory.updateRobots = function() {
      const head = document.querySelector("head");
      if(head) {
        const robotsElement = document.querySelector("head meta[name='robots']");
        const contentValue = robotsElement ? robotsElement.getAttribute("content").toLowerCase() : "";
        const url = window.location.origin + window.location.pathname.substring(0, window.location.pathname.lastIndexOf( "/" ) + 1);
        if (!robotsElement || contentValue === "all" || (contentValue.indexOf("index") !== -1 && contentValue.indexOf("follow") !== -1)) {
          const xhr = new XMLHttpRequest();
          xhr.open("GET", "/apps/ohcsearchclient/api/v1/search/robots?url=" + encodeURIComponent(url));
          xhr.send();
          xhr.onload = function () {
            if (xhr.status === 200 && xhr.responseText !== "all") {
              if (robotsElement) {
                robotsElement.setAttribute("content", xhr.responseText);
              } else {
                const newRobotsElement = document.createElement("meta");
                newRobotsElement.name = "robots";
                newRobotsElement.content = xhr.responseText;
                head.appendChild(newRobotsElement);
              }
            }
          };
        } 
      }
    };

    InlineHelperFactory.getSearchText = function() {
      let searchText = null;
      let metaDcTermsTitle = document.querySelectorAll('meta[name="dcterms.title"]')[0];
      let contentDcTermsTitle = metaDcTermsTitle && metaDcTermsTitle.getAttribute('content');
      let docTitle = document.title;
      if (['/', 'index.html', 'index.htm', 'toc.htm', 'preface.html', 'preface.htm', 'title.html', 'title.htm', 'lot.html', 'lot.htm', 'lof.html', 'lof.htm', 'loe.html', 'loe.htm', 'glossary.html', 'glossary.htm'].some(extension => location.pathname.endsWith(extension))) {
        if(contentDcTermsTitle && contentDcTermsTitle.trim().length > 0) {
          searchText = contentDcTermsTitle.trim();
        } else if(docTitle && docTitle.trim().length > 0) {
          searchText = docTitle.trim();
        }
      } else {
        if(docTitle && docTitle.trim().length > 0) {
          searchText = docTitle.trim();
        } else if(contentDcTermsTitle && contentDcTermsTitle.trim().length > 0) {
          searchText = contentDcTermsTitle.trim();
        }
      }
      if(!searchText || searchText.length == 0) {
        let heading = document.querySelector("article h1, article h2, h1, h2");
        let headingText = heading.innerText || heading.textContent;
        if(headingText && headingText.trim().length > 0) {
          searchText = headingText.trim();
        }
      }
      return searchText || ' ';
    }

    InlineHelperFactory.addReleaseNoticesInlineBanner = function() {
        const mainDivOhcGrid = document.querySelectorAll('body > header')[0] ? document.querySelectorAll('body > header')[0] : 
          document.querySelectorAll('body > div > main')[0];
        const alreadyExistedComponent = document.getElementsByClassName('release-notices-css');
        const thisUrlPathName = window.location.pathname;
        if(mainDivOhcGrid && alreadyExistedComponent.length <= 0) {
          const jsonContentReleaseNoticesUrl = '/notices/release-notices.json';
          const bannerDiv = document.createElement('div');
          bannerDiv.className = 'release-notices-container';
          const cacheSetting = $.ajaxSetup().cache;
          $.ajaxSetup({cache:true});
          $(bannerDiv).load(jsonContentReleaseNoticesUrl, function(responseTxt, statusTxt, xhr){
            $.ajaxSetup({cache:cacheSetting});
            if(statusTxt == "success") {
              const jsonParsedRelease = JSON.parse(responseTxt);
              let notFoundIndex = true;
              for(let index = 0; notFoundIndex && jsonParsedRelease && index < jsonParsedRelease[PRODUCT_GROUP].length; index++) {
                const previousReleasesSubName = jsonParsedRelease[PRODUCT_GROUP][index][PREVIOUS_RELEASES];
                const searchEnabled = jsonParsedRelease[PRODUCT_GROUP][index][SEARCH_ENABLED];
                if(previousReleasesSubName) {
                  for(let subIndex = 0; notFoundIndex && previousReleasesSubName && subIndex < previousReleasesSubName.length; subIndex++){
                    const nameInBannerDivPreviousReleases = new RegExp(jsonParsedRelease[PRODUCT_GROUP][index][PREVIOUS_RELEASES][subIndex],"g");
                    const metaNameDcTerms = document.querySelectorAll('meta[name="dcterms.isVersionOf"]')[0];
                    const contentNameRole = metaNameDcTerms && metaNameDcTerms.getAttribute('content') ? 
                      metaNameDcTerms.getAttribute('content').toLowerCase() : '*';
                    if(nameInBannerDivPreviousReleases && thisUrlPathName.search(nameInBannerDivPreviousReleases) !== -1) {    
                      const nameInBannerDivLatestDocs = jsonParsedRelease[PRODUCT_GROUP][index][LATEST_DOCS]; 
                      const urlToGetAfterVerify = nameInBannerDivLatestDocs[contentNameRole] ? 
                        nameInBannerDivLatestDocs[contentNameRole] : nameInBannerDivLatestDocs[contentNameRoleGeneral];
                      InlineHelperFactory.addReleaseNoticesStyle(bannerDiv, "release-notices-css", jsonParsedRelease[PRODUCT_GROUP][index], urlToGetAfterVerify);  
                      mainDivOhcGrid.parentNode.insertBefore(bannerDiv, mainDivOhcGrid);
                      notFoundIndex = false;
                      //add iframe and change banner button after iframe finishes
                      if(searchEnabled && metaNameDcTerms) {
                        let iframe = document.createElement("iframe");
                        iframe.style.display = "none";
                        iframe.src = urlToGetAfterVerify;
                        document.body.appendChild(iframe);
                        iframe.addEventListener("load", function() {
                          let targetProductMeta = iframe.contentWindow.document.querySelectorAll("meta[name='dcterms.product']")[0];
                          let targetProduct = targetProductMeta && targetProductMeta.getAttribute('content');
                          targetProduct = targetProduct && targetProduct.split(";")[0];
                          let targetBookMeta = iframe.contentWindow.document.querySelectorAll("meta[name='dcterms.isVersionOf']")[0];
                          let targetBook = targetBookMeta && targetBookMeta.getAttribute('content');
                          let searchTarget = "/apps/ohcsearchclient/api/v2/search/luckypages";
                          if(targetBook) {
                            searchTarget += "?library=" + encodeURIComponent(targetProduct);
                            searchTarget += "&book=" + encodeURIComponent(targetBook) + "&q=";
                          } else if(targetProduct) {
                            searchTarget += "?product=" + encodeURIComponent(targetProduct) + "&q=";
                          } else {
                            searchTarget += "?q="
                          }
                          document.querySelector(".release-notices-container .button-integration").onclick = function() { window.location.href = searchTarget + encodeURIComponent(InlineHelperFactory.getSearchText()) };
                        });
                      }
                    }
                  }
                }
                const promoReleasesSubName = jsonParsedRelease[PRODUCT_GROUP][index][PROMO_RELEASES];
                if(promoReleasesSubName) {
                  for(let subIndex = 0; notFoundIndex && promoReleasesSubName && subIndex < promoReleasesSubName.length; subIndex++){
                    const nameInBannerDivPromoReleases = new RegExp(jsonParsedRelease[PRODUCT_GROUP][index][PROMO_RELEASES][subIndex],"g");
                    if(nameInBannerDivPromoReleases && thisUrlPathName.search(nameInBannerDivPromoReleases) !== -1) {    
                      InlineHelperFactory.addReleaseNoticesStyle(bannerDiv, "release-notices-css promo", jsonParsedRelease[PRODUCT_GROUP][index]);  
                      mainDivOhcGrid.parentNode.insertBefore(bannerDiv, mainDivOhcGrid);
                      notFoundIndex = false;
                    }
                  }
                }
              }
            }
            if(statusTxt == "error")
              console.log("Error: " + xhr.status + ": " + xhr.statusText);
          });
        }
      };

      InlineHelperFactory.addReleaseNoticesStyle = function(bannerDiv, divClasses, jsonParsedRelease, urlToGetAfterVerify) {
        const divBannerImg = '<div><div class="img-warning"></div></div>'; 
        const divBannerText = '<div class="release-text">' + jsonParsedRelease['banner-text'] + '</div>';
        const divBannerButtonIntegration = urlToGetAfterVerify ? '<button class="button-integration" onclick="window.location.href = \'' 
          + urlToGetAfterVerify + '\'">' 
          + (jsonParsedRelease['button-text'] ? jsonParsedRelease['button-text'] : 'Go to Latest Release') 
          + '</button>' : '';
        const divBannerOnClickHide = 'onclick="document.getElementsByClassName(\'release-notices-container\')[0].setAttribute(\'style\',\'display: none !important\'); "';
        const divBannerButtonClose = '<button class="button-close" ' + divBannerOnClickHide + '>Close this notice</button>';
        const divBannerSpanSpaceMax = '<span class="space-max"></span>';
        const divBannerSpanSpaceMin = '<span class="space-min"></span>';
        const divBannerSpanSpaceAux = '<span class="space-aux"></span>';
        const divBannerAuxDiv = divBannerSpanSpaceAux + '<div class="div-aux">' + divBannerImg + divBannerSpanSpaceMax + 
          divBannerText + divBannerSpanSpaceMax + '</div>';
        const divBannerAuxDivButtons = '<div class="div-aux-buttons">' +divBannerButtonIntegration + divBannerSpanSpaceMin + 
          divBannerButtonClose + '</div>' + divBannerSpanSpaceAux;
        const divBanner = '<div class="' + divClasses + '">' + divBannerAuxDiv + divBannerAuxDivButtons + '</div>'
        $(bannerDiv).html(divBanner);
      };

      return InlineHelperFactory;
});
if (!window.console) {
    window.console = {
        log: function () {
        }
    };
}

define('rest-main',["require", "bookish-main", "jquery", "ohc-url", "tracking-wrapper", "handlebars", "jsonpointer", "docson", "text!../../ohc-common/templates/bookish.hbs",
    "text!../../ohc-common/templates/utility-bar/preview.hbs", "text!../../ohc-common/templates/embed.hbs", "marked",
    "text!../../ohc-common/templates/utility-bar/scope/scopechip.hbs", "utility-bar", "inline-helper-factory"],
        function (require, common, $, ohcurl , tracking, handlebars, jsonpointer, docson, bookTemplate, utilityPreviewTemplate, embedTemplate, 
            marked, scopeChip, utilityBar, inlineHelper) {
            marked.setOptions({
                renderer: new marked.Renderer(),
                gfm: true,
                tables: true,
                breaks: true,
                pedantic: false,
                sanitize: true,
                smartLists: true,
                smartypants: false
            });

            //possibly before dom
            var currentUrl = $.parseURL(window.location.href);
            if(window.top === window && typeof currentUrl.params.embed === "undefined") {
                var template = handlebars.compile(bookTemplate);
            } else if (typeof currentUrl.params.embed !== "undefined" && currentUrl.params.embed == 0) {
                var template = handlebars.compile(bookTemplate);
            } else {
                var template = handlebars.compile(embedTemplate);
            }

            //init docson
            docson.templateBaseUrl = require.toUrl("docson-templates");

            //after dom
            $(function () {
                
                var pubProductName = $("meta[name='dcterms.product']").attr('content');
                if (pubProductName === "en/cloud/paas/digital-assistant") {
                    $('head').append('<script type="text/javascript" src="/en/dcommon/artie/js/artie.js"></script>');
                } else if (pubProductName === "en/cloud/paas/application-integration") {
                    $('head').append('<script type="text/javascript" src="/en/dcommon/oic3_assistant/js/artie.js"></script>');
                }

                var data = common.getTemplateData();
                /*
                var pagePromise = $.when(common.loadToc());

                pagePromise.done(function (toc) {
                    data.tabtoc = toc;
                });

                pagePromise.fail(function (error) {
                    console.log(error);
                });


                pagePromise.always(function() {
                */
                    data.tabtoc = '<header class="clearfix"><h2>Table of Contents</h2></header>' +
                    '<p class="text-center">' +
                    '<span class="fa fa-spinner fa-pulse fa-3x fa-fw" aria-hidden="true"></span>' +
                    '<span class="sr-only">Loading...</span>' +
                    '</p>';
                    if(data.book) {
                        data.tabsearch = true;
                    }
                    data.tabprint = true;

                    //file out data for handlebar template
                    data.pubType = "rest";

                    data.article = $("article").html();

                    //populate template and place in body
                    $("body").html(template(data));

                    if(ohcurl.isOracle()) utilityBar.init(utilityPreviewTemplate);

                    common.templateInit();

                    utilityBar.rewriteBookParams();
                    utilityBar.handleScopeParams(scopeChip);

                    $(document).on("articleload", function () {
                        common.renderArticle();
                        renderArticle();
                        common.showArticle();
                    });
                    $(document).on("articlefail", function (error) {
                        console.log(error);
                        common.showError();
                    });
                    common.renderArticle();
                    renderArticle();
                    common.showArticle(false);
                    addRadioButtonsAccessibility();
                    addDropDownAccessibility();
                 
                    if(currentUrl.protocol.indexOf("http") === 0) {
                        if (tracking.isTrackingEnabled()) {
                            setTimeout(function(){
                                $.getScript("https://www.oracleimg.com/us/assets/metrics/ora_docs.js");
                                tracking.applyTracking();
                            }, 200);
                        }
                    }

                /*
                });
                */
               if(ohcurl.isOracle()) {
                inlineHelper.updateRobots();
                inlineHelper.addReleaseNoticesInlineBanner();
               } else {
                utilityBar.hideSearchBar();
              }
            });

            function addDropDownAccessibility() {
                var $dropdown = $('div.dropdown.btn-group')
                $("ul.dropdown-menu").attr("role","menu");
                $("ul.dropdown-menu li").attr('role','presentation');
                $("ul.dropdown-menu li a").attr( {role:'presentation', tabindex: '-1'});
                $('li.next a.btn:first').focusin(function () {
                    $dropdown.removeClass('open')
                  });
                  $("section").find("a:first").focusin(function () {
                    $dropdown.removeClass('open')
                  });
            }

            function addRadioButtonsAccessibility() {
                $("div#sortby.btn-group").attr("role","tablist");
                $("label.btn.btn-primary").children().attr("role","tab");
                $('label.btn.btn-primary:nth-child(1) input').attr({
                    id:"summary", 
                    "aria-controls":"summary-sort",
                });
                $('label.btn.btn-primary:nth-child(2) input').attr({
                    id:"path", 
                    "aria-controls":"path-sort",
                });
                $('label.btn.btn-primary:nth-child(3) input').attr({
                    id:"method", 
                    "aria-controls":"method-sort",
                });

                $("div.tab-content").children().attr("tabindex", "0");
                $("div#summary-sort").attr("aria-labelledby", "summary");
                $("div#path-sort").attr("aria-labelledby","path");
                $("div#method-sort").attr("aria-labelledby","method");

                //for grouped tab panels
                $("div#summary-sort-grouped").attr("aria-labelledby", "summary");
                $("div#summary-sort-ungrouped").attr("aria-labelledby", "summary");
                $("div#path-sort-grouped").attr("aria-labelledby","path");
                $("div#path-sort-ungrouped").attr("aria-labelledby","path");
                $("div#method-sort-grouped").attr("aria-labelledby","method");
                $("div#method-sort-ungrouped").attr("aria-labelledby","method");
            }

            function renderArticle() {
                var before = $("head link[rel=prev]");
                var after = $("head link[rel=next]");
                if (!before.length && !after.length) {
                    //make sure they aren't stuck on a page outside of the TOC
                    $("article .ohc-pager .next").removeClass("disabled").find("a").attr("href", "index.html").on("click", common.handleInternalClick);
                }

                //enable GFM for some elements as long as they don't have HTML children
                $("article div.description, #request dd>div, #response dd>div, #request > .panel > .panel-body, #response > .panel > .panel-body").each(function() {
                    var d = $(this);
                    if (d.children().length === 0 ) {
                        d.html(marked(d.html().trim()));
                    }
                });

                //enable in-article rest breadcrumb
                $('article .breadcrumb a').tooltip({placement: "bottom"});
                renderSwagger();
                handleEndpointsForm();
                handleAltCollapse();
                handleShowSchemaSource();
                handleExpandPropertyDescription();
                handleSelectExample();
                handleExpandResourcesDescription();
                //panel chevron handling
                $("article .panel-collapse").on('show.bs.collapse', function () {
                    $(this).siblings(".panel-heading").find(".glyphicon-chevron-right").removeClass("glyphicon-chevron-right").addClass("glyphicon-chevron-down");
                });
                $("article .panel-collapse").on('hide.bs.collapse', function () {
                    $(this).siblings(".panel-heading").find(".glyphicon-chevron-down").addClass("glyphicon-chevron-right").removeClass("glyphicon-chevron-down");
                });

                $("article div.schema-summary:not(:has(*))").each(function(){
                    $(this).parent().find("a[data-toggle='prop-collapse']").replaceWith(function () {
                        return $("<span/>").append($(this).contents());
                    });
                });
            }

            function handleExpandPropertyDescription() {
                $("article .schema-container [data-toggle=prop-collapse]").on("click", function(e) {
                    e.preventDefault();
                    e.stopImmediatePropagation();
                    var el = $(document.getElementById($(this).attr("href").split('#')[1]));
                    $(this).attr('aria-expanded', ($(this).attr('aria-expanded') == "false" ? true : false));
                    el.collapse("toggle");
                });
            }

            function handleExpandResourcesDescription() {
                $('#toggle-icon, #resouces_information-btn').click(function(){
                    var expanded = $('#toggle-icon').attr('aria-expanded') === 'true';
                    if (expanded) {
                        $('#toggle-icon').removeClass('oj-ux-ico-chevron-down').addClass('oj-ux-ico-chevron-right');
                    } else {
                        $('#toggle-icon').removeClass('oj-ux-ico-chevron-right').addClass('oj-ux-ico-chevron-down');
                    }

                });
            }

            function renderSwagger() {
                var docsonRender = function () {
                    //docson handling
                    $(".json-schema").each(function () {
                        var pointer = $(this).attr("data-pointer");
                        var value = jsonpointer.get(window.swagger, pointer);
                        if (!$.isEmptyObject(value)) {
                            docson.doc($(this), window.swagger, pointer);
                        } else {
                            $(this).addClass("hidden");
                        }
                    });
                };

                if ($(".json-schema").length > 0) {
                    //only for old docson style schema rendering
                    if (!window.swagger) {
                        $(".json-schema").html('<i class="fa fa-cog fa-spin"></i> Loading Swagger...');
                        var swaggerXhr = $.getJSON("swagger.json");
                        swaggerXhr.done(function (data) {
                            $(".json-schema").empty();
                            window.swagger = data;
                            docsonRender();
                        });
                        swaggerXhr.error(function () {
                            $(".json-schema").empty();
                            $(".json-schema").html('<i class="fa fa-exclamation-triangle"></i> Failed to load swagger.json');
                            console.log("Failed to load swagger.json");
                        });
                    } else {
                        docsonRender();
                    }
                } else {
                    // new style schema display
                    $("article .schema-container").each(function(){
                      /*if is a body schema*/
                      if($(this).children().first().is(".swagger-schema")) {
                        $(this).find(".swagger-schema:first").each(function(){
                          var id = $(this).attr("id");
                          var panelText = $(this).find(".panel-heading:first").text();
                          panelText = panelText.substr(panelText.indexOf(":")+1).trim();
                          $(this).closest(".schema-container").each(function(){
                              //UX update
                              if($(this).closest(".entity").length > 0) {
                                  $(this).closest(".entity").find(".schema-path").html("<ol class='schema-breadcrumbs'><li class='active' data-id='" + id + "'>" + panelText + "</li></ol>");
                              } else {
                                $(this).prepend("<span class='hidden-print bold'>Object: </span><ol class='schema-breadcrumbs'><li class='active' data-id='" + id + "'>" + panelText + "</li></ol>");
                              }
                          });

                        });
                      }
                    });


                    var schemaChange = function(e) {
                      var newUx = $(this).closest(".entity").length > 0;
                      var that = this;
                      e.preventDefault();
                      e.stopImmediatePropagation();
                      if($(that).is(":disabled")) {
                          return false;
                      }
                      $(that).attr("disabled", "disabled");
                      if(newUx) {
                        var currentSchema = $(this).closest(".entity").find(".schema-container > .swagger-schema:visible:first, .schema-container > .schema-properties:visible:first");
                      } else {
                          var currentSchema = $(this).closest(".schema-container").find("> .swagger-schema:visible:first, > .schema-properties:visible:first");
                      }
                      var target = $(this).attr("href");
                      if(target == "#") {
                        if(newUx) {
                            var newSchema = $(this).closest(".entity").find(".schema-container").find("> .schema-properties");
                            $(this).closest(".entity").find(".schema-breadcrumbs").prev().remove().end().remove();
                        } else {
                            var newSchema = $(this).closest(".schema-container").find("> .schema-properties");
                            $(this).closest(".schema-container").find(".schema-breadcrumbs").prev().remove().end().remove();
                        }
                      } else {
                        var newSchema = $(document.getElementById(target.substr(1)));
                      }


                      if ($(that).hasClass('btn') && !newUx) {
                          newSchema.find(".panel-collapse:first").collapse('hide');
                      }

                      if(newUx) {
                        var container = currentSchema.closest(".entity");
                      } else {
                          var container = currentSchema.parents(".panel").last();
                      }
                      var previousCss  = newSchema.attr("style");
                      newSchema.css({
                        position: 'absolute',
                        visibility:'hidden',
                        display: 'block'
                      });
                      var newHeight = newSchema.outerHeight();
                      container.css("min-height", container.height() - currentSchema.height() + newHeight - (newUx?10:0) + "px");
                      newSchema.attr("style", previousCss ? previousCss : "");
                      currentSchema.fadeToggle("fast", function() {
                        if(newUx) {
                            var breadcrumbs = newSchema.closest(".entity").find(".schema-breadcrumbs");
                        } else {
                            var breadcrumbs = newSchema.closest(".schema-container").find(".schema-breadcrumbs");
                        }
                        if(breadcrumbs.length === 1) {
                            var oldCrumb = breadcrumbs.find(".active");
                            oldCrumb.removeClass("active");
                            var oldCrumbId = oldCrumb.attr("data-id");
                            oldCrumb.wrapInner("<a href='#" + oldCrumbId + "'></a>");
                        } else if(target != "#") {
                            $(this).closest(".schema-container").each(function(){
                              //UX update
                              if(newUx) {
                                  $(this).closest(".entity").find(".schema-path").html("<ol class='schema-breadcrumbs'><li data-id='schema-properties'><a href='#'>Query Parameters</a></li></ol>");
                                  breadcrumbs = newSchema.closest(".entity").find(".schema-breadcrumbs");
                              } else {
                                  $(this).closest(".schema-container").prepend("<span class='hidden-print'>Object: </span><ol class='schema-breadcrumbs'><li data-id='schema-properties'><a href='#'>Query Parameters</a></li></ol>");
                                  breadcrumbs = newSchema.closest(".schema-container").find(".schema-breadcrumbs");
                              }
                            });
                        }
                        breadcrumbs.find('a').off();
                        breadcrumbs.find('a').one("click", schemaChange);
                        if($(that).closest(".schema-breadcrumbs").length == 1) {
                            $(that).closest("li").nextAll().addBack().remove();
                        }
                        var newCrumbId = newSchema.attr("id");
                        var panelText = newSchema.find(".panel-heading:first").text();
                        panelText = panelText.substr(panelText.indexOf(":")+1).trim();
                        breadcrumbs.append("<li class='active' data-id='" + newCrumbId + "'>" + panelText + "</li>");


                        var bottomOfScreen = $(window).scrollTop() + $(window).height();
                        var topOfScreen = $(window).scrollTop();
                        var elementTop = breadcrumbs.offset().top;

                        if(elementTop < topOfScreen || elementTop > bottomOfScreen) {
                          $('html, body').animate({
                                scrollTop: elementTop - 16
                            }, 'fast');
                        }

                        newSchema.fadeToggle("fast", function() {
                          $(that).removeAttr("disabled");
                          $("article .schema-properties a.btn, article .schema-items a.btn").off().one("click", schemaChange);
                          container.css("min-height","");
                        });
                      });
                    };

                    $("article .schema-properties a.btn, article .schema-items a.btn").off().one("click", schemaChange);
                }
            }

            function handleEndpointsForm() {
                //tab swapping on endpoint and api pages
                $("article form.endpoints select").add("article form.endpoints input").change(function (e) {
                    var tabToShow;
                    var groupedStyle = true;
                    // summary, path, or method
                    var sortMethod = $("#sortby input[name=sort-radio]:checked").val();
                    if ($("#grouped").length > 0) {
                        var seedPanel = "summary-sort-grouped";
                        if ($("#grouped").prop('checked')) {
                            tabToShow = sortMethod + "-sort-grouped";
                        } else {
                            groupedStyle = false;
                            tabToShow = sortMethod + "-sort-ungrouped";
                        }
                    } else {
                        var seedPanel = "summary-sort";
                        tabToShow = sortMethod + "-sort";
                    }
                    var anchor = $("<a href='#' data-target='#" + tabToShow + "'>link</a>");
                    var targetTabPanel = $(document.getElementById(tabToShow));
                    if (targetTabPanel.is(':empty')){
                        var sourceTabPanel = $(document.getElementById(seedPanel));

                        function sortEndpoints(panel) {
                            panel.find("dl.schema-properties").each(function() {
                                $(this).children("dt").sort(function(a, b){
                                    var $a = $(a);
                                    var $b = $(b);

                                    var da = $a.next("dd");
                                    var db = $b.next("dd");

                                    var summaryA = $a.text().trim().toLowerCase();
                                    var methodA = da.find("span").first().text();
                                    var pathA = da.find("code").first().text();

                                    var summaryB = $b.text().trim().toLowerCase();
                                    var methodB = db.find("span").first().text();
                                    var pathB = db.find("code").first().text();

                                    var pathOrder = pathA < pathB ? -1 : (pathA > pathB ? 1 : 0);
                                    var methodOrder = methodA < methodB ? -1 : (methodA > methodB ? 1 : 0);
                                    var summaryOrder = summaryA < summaryB ? -1 : (summaryA > summaryB ? 1 : 0);


                                    if(sortMethod == "summary") {
                                        if(summaryOrder != 0) {
                                            return summaryOrder;
                                        } else if (pathOrder != 0){
                                            return pathOrder;
                                        } else {
                                            return methodOrder;
                                        }
                                    } else if(sortMethod == "method") {
                                        if(methodOrder != 0) {
                                            return methodOrder;
                                        } else {
                                            return pathOrder;
                                        }
                                    } else { // path
                                        if(pathOrder != 0) {
                                            return pathOrder;
                                        } else {
                                            return methodOrder;
                                        }
                                    }
                                }).each(function() {
                                    var dd = $(this).next("dd");
                                    $(this).appendTo($(this).parent());
                                    dd.appendTo(dd.parent());
                                })
                            });
                        }

                        var frag = $("<div>");
                        if(groupedStyle) {
                            //clone each "> .panel" and sort each dl
                            sourceTabPanel.find("> .panel").each(function(){
                                var panelClone = $(this).clone();
                                sortEndpoints(panelClone);
                                panelClone.appendTo(frag);
                            });
                        } else {
                            //combine all endpoints into a single dl and sort it
                            var newPanel = $("<div class='panel panel-default'><div class='panel-heading'>All Endpoints</div><div class='panel-body'><dl class='list-group schema-properties'></dl></div></div>");
                            var newDl = newPanel.find("dl.schema-properties");
                            var defs = [];
                            sourceTabPanel.find("> .panel").each(function(){
                                defs.push($(this).find("dl.schema-properties").html());
                            });
                            newDl.html(defs.join(''));
                            defs = null;
                            sortEndpoints(newPanel);
                            newPanel.appendTo(frag);
                        }
                        targetTabPanel.html(frag.html());
                    }
                    /*
                    targetTabPanel.siblings(".active").removeClass("active");
                    targetTabPanel.addClass("active");
                    */
                    anchor.tab("show");
                });
            }

            function handleShowSchemaSource() {
              $("article a[data-toggle='schema-view']").mouseup(function(e){
                $(this).blur();
              });

                $("article a[data-toggle='schema-view']").click(function(e){
                    e.preventDefault();
                    e.stopImmediatePropagation();
                    //var ss = $(this).closest(".swagger-schema");
                    var ss = $(this).parent();
                    var thing1 = $(this).next();
                    var thing2 = thing1.next();
                    ss.css("minHeight", ss.height());
                    if($(this).text()=="Show Source") {
                        $(this).text("Hide Source");
                        $(this).addClass("hide-source");
                        thing1.fadeOut("fast", function() {
                            thing2.fadeIn("fast", function(){
                                ss.css("minHeight", "");
                            });
                        });
                    } else {
                        $(this).text("Show Source");
                        $(this).removeClass("hide-source");
                        thing2.fadeOut("fast", function() {
                            thing1.fadeIn("fast", function() {
                                ss.css("minHeight", "");
                            });
                        });
                    }
                });
            }

            function handleAltCollapse() {
                $("article [data-toggle=alt-collapse]").on("click", function(e) {
                    e.preventDefault();
                    e.stopImmediatePropagation();
                    var el = $(document.getElementById($(this).attr("href").split('#')[1]));

                    el.one('shown.bs.collapse', function () {
                        var bottomOfScreen = $(window).scrollTop() + $(window).height();
                        var topOfScreen = $(window).scrollTop();
                        var elementTop = el.offset().top;

                        if(elementTop < topOfScreen || elementTop > bottomOfScreen) {
                          $('html, body').animate({
                                scrollTop: elementTop - 40
                            }, 'fast');
                        }
                    });

                    el.collapse("toggle");
                });
            }


            function handleSelectExample() {
                $('article select[id^="example"]').on("change", function(e) {
                    e.preventDefault();
                    e.stopImmediatePropagation();

                    const selectedValue = JSON.parse(document.getElementById(e.target.id).value);
                    document.getElementById("selectedDescriptionValue-" + e.target.id).innerHTML = selectedValue.description ? selectedValue.description : "";
                    document.getElementById("selectedCodeValue-" + e.target.id).innerHTML = JSON.stringify(selectedValue.value,  null, 4);
                    document.getElementById("code-" + e.target.id).style.display = "block";
                });
            }

        });

